<?php

declare(strict_types=1);

namespace Nesto\Orm\Attributes;

use Attribute;

/**
 * Auto-generated primary key (TypeORM's @PrimaryGeneratedColumn(strategy, options)).
 *
 *   #[PrimaryGeneratedColumn] public int $id;                     // 'increment': AUTOINCREMENT / AUTO_INCREMENT / BIGSERIAL
 *   #[PrimaryGeneratedColumn('uuid')] public string $id;          // UUID v4: PostgreSQL DEFAULT gen_random_uuid(),
 *                                                                 // generated by the ORM on the other databases
 *   #[PrimaryGeneratedColumn('identity')] public int $id;         // PostgreSQL GENERATED BY DEFAULT AS IDENTITY
 *   #[PrimaryGeneratedColumn('identity', generatedIdentity: 'ALWAYS')] public int $id;
 *   #[PrimaryGeneratedColumn(type: 'int')] public int $id;        // column type (default bigint)
 *
 * 'rowid' is accepted as 'increment'. `type: 'uuid'` (older spelling) means the uuid strategy.
 */
#[Attribute(Attribute::TARGET_PROPERTY)]
final class PrimaryGeneratedColumn
{
    public const STRATEGIES = ['increment', 'uuid', 'identity', 'rowid'];

    public function __construct(
        public readonly string $strategy = 'increment',
        public readonly ?string $name = null,
        public readonly ?string $type = null,
        public readonly ?string $comment = null,
        public readonly ?string $generatedIdentity = null,
    ) {}

    /** increment / uuid / identity / rowid. */
    public function strategy(): string
    {
        return $this->type === 'uuid' ? 'uuid' : $this->strategy;
    }

    /** Column type: uuid for the uuid strategy, else the given integer type (bigint by default). */
    public function columnType(): string
    {
        if ($this->strategy() === 'uuid') {
            return 'uuid';
        }

        return $this->type ?? 'bigint';
    }
}
